<?php
require_once __DIR__ . '/config.php'; require_admin(); $pageTitle='Administrar productos — Lechugas'; $activePage=''; $error=''; $notice=''; $pdo=db();
if ($_SERVER['REQUEST_METHOD']==='POST') {
    csrf_check(); $action=$_POST['action']??'';
    if ($action==='delete') { $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT); if($id){$pdo->prepare('UPDATE productos SET activo=0 WHERE id=?')->execute([$id]);$notice='Producto retirado de la tienda.';} }
    elseif ($action==='save') {
        $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT)?:null; $nombre=trim($_POST['nombre']??''); $desc=trim($_POST['descripcion']??''); $price=filter_input(INPUT_POST,'precio',FILTER_VALIDATE_FLOAT); $stock=filter_input(INPUT_POST,'stock',FILTER_VALIDATE_INT); $image=trim($_POST['imagen']??'');
        if($nombre===''||mb_strlen($nombre)>120||$price===false||$price<=0||$stock===false||$stock<0) $error='Revisa el nombre, precio y existencias.';
        else { if($id) $pdo->prepare('UPDATE productos SET nombre=?,descripcion=?,precio=?,stock=?,imagen=?,activo=1 WHERE id=?')->execute([$nombre,$desc,$price,$stock,$image?:null,$id]); else $pdo->prepare('INSERT INTO productos (nombre,descripcion,precio,stock,imagen) VALUES (?,?,?,?,?)')->execute([$nombre,$desc,$price,$stock,$image?:null]); $notice='Producto guardado correctamente.'; }
    }
}
$editing=null; if(isset($_GET['editar'])){$stmt=$pdo->prepare('SELECT * FROM productos WHERE id=?');$stmt->execute([filter_input(INPUT_GET,'editar',FILTER_VALIDATE_INT)]);$editing=$stmt->fetch();}
$products=$pdo->query('SELECT * FROM productos ORDER BY activo DESC,nombre')->fetchAll();
require __DIR__ . '/includes/header.php'; ?>
<main><section class="page-hero"><div class="container"><span class="eyebrow">PANEL DE ADMINISTRACIÓN</span><h1>Gestiona tu <em>cosecha.</em></h1><p>Agrega, edita o retira productos de la tienda.</p></div></section><section class="section-pad"><div class="container admin-grid"><div class="admin-form"><span class="eyebrow"><?= $editing?'EDITAR PRODUCTO':'NUEVO PRODUCTO' ?></span><h2><?= $editing?'Actualiza los datos':'Agregar a la tienda' ?></h2><?php if($error): ?><div class="alert alert-warning"><?= e($error) ?></div><?php endif; ?><?php if($notice): ?><div class="alert alert-success"><?= e($notice) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($editing['id']??0) ?>"><label class="form-label">Nombre</label><input class="form-control mb-3" name="nombre" maxlength="120" required value="<?= e($editing['nombre']??'') ?>"><label class="form-label">Descripción</label><textarea class="form-control mb-3" name="descripcion" rows="3"><?= e($editing['descripcion']??'') ?></textarea><div class="row"><div class="col-6"><label class="form-label">Precio (COP)</label><input class="form-control mb-3" type="number" name="precio" min="1" step="100" required value="<?= e((string)($editing['precio']??'')) ?>"></div><div class="col-6"><label class="form-label">Existencias</label><input class="form-control mb-3" type="number" name="stock" min="0" required value="<?= e((string)($editing['stock']??0)) ?>"></div></div><label class="form-label">Ruta de imagen (opcional)</label><input class="form-control mb-3" name="imagen" placeholder="img/lechuga.jpg" value="<?= e($editing['imagen']??'') ?>"><button class="btn btn-leaf rounded-pill">Guardar producto ↗</button><?php if($editing): ?> <a class="btn btn-outline-dark rounded-pill" href="admin_productos.php">Cancelar</a><?php endif; ?></form></div><div class="admin-list"><h2>Productos registrados</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Producto</th><th>Precio</th><th>Stock</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><strong><?= e($p['nombre']) ?></strong></td><td><?= money($p['precio']) ?></td><td><?= (int)$p['stock'] ?></td><td><?= $p['activo']?'Activo':'Retirado' ?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-dark rounded-pill" href="?editar=<?= (int)$p['id'] ?>">Editar</a><?php if($p['activo']): ?><form method="post" class="d-inline" onsubmit="return confirm('¿Retirar este producto de la tienda?')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="btn btn-sm btn-outline-danger rounded-pill">Eliminar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><p class="admin-hint">Las ventas registradas se conservan aunque retires un producto.</p></div></div></section></main><?php require __DIR__ . '/includes/footer.php'; ?>
